<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ubuntu Desktop Environment</title>
    <style>
        :root {
            --bg-color: #2c3e50;
            --taskbar-bg: rgba(20, 20, 20, 0.9);
            --window-bg: #f0f0f0;
            --accent: #e95420; /* Ubuntu Orange */
            --text-color: #333;
            --border-radius: 8px;
        }

        * { box-sizing: border-box; margin: 0; padding: 0; }

        body, html {
            height: 100%;
            overflow: hidden;
            font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
        }

        #desktop {
            width: 100vw;
            height: 100vh;
            background: linear-gradient(135deg, #1e3c72 0%, #2a5298 100%);
            position: relative;
            overflow: hidden;
        }

        /* Taskbar / Dock */
        #taskbar {
            position: fixed;
            bottom: 0;
            width: 100%;
            height: 60px;
            background: var(--taskbar-bg);
            backdrop-filter: blur(10px);
            display: flex;
            align-items: center;
            padding: 0 20px;
            gap: 20px;
            border-top: 1px solid rgba(255,255,255,0.1);
            z-index: 9999;
        }

        #taskbar button {
            padding: 10px 20px;
            border-radius: var(--border-radius);
            border: none;
            background: rgba(255,255,255,0.1);
            color: white;
            cursor: pointer;
            transition: background 0.2s;
        }

        #taskbar button:hover {
            background: rgba(255,255,255,0.2);
        }

        /* Windows */
        .window {
            position: absolute;
            min-width: 360px;
            min-height: 240px;
            background: var(--window-bg);
            border-radius: 8px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
            display: none; /* Hidden by default */
            flex-direction: column;
            overflow: hidden;
            border: 1px solid #999;
        }

        .window.active { display: flex; }

        .title-bar {
            background: #ddd;
            padding: 8px 12px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 1px solid #ccc;
            cursor: move;
        }

        .title-bar .title { font-weight: bold; font-size: 0.9em; }

        .win-close {
            background: #ff5f56;
            border: none;
            border-radius: 50%;
            width: 20px;
            height: 20px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 12px;
        }

        .window-content {
            flex-grow: 1;
            padding: 15px;
            overflow: auto;
        }

        /* Files App Styling */
        #files-path {
            margin-bottom: 10px;
            font-size: 0.85em;
            color: #666;
            background: #eee;
            padding: 4px 8px;
            border-radius: 4px;
            display: inline-block;
        }

        #files-list {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
            gap: 15px;
        }

        .fs-item {
            padding: 10px;
            text-align: center;
            cursor: pointer;
            border-radius: 4px;
            transition: background 0.2s;
            user-select: none;
        }

        .fs-item:hover { background: rgba(0,0,0,0.1); }
        .fs-item.folder::before { content: "📁 "; }
        .fs-item.file::before { content: "📄 "; }

        #files-up {
            margin-bottom: 20px;
            padding: 5px 10px;
            cursor: pointer;
        }

        /* Notepad App Styling */
        #tabs {
            display: flex;
            background: #ccc;
            border-bottom: 1px solid #bbb;
            overflow-x: auto;
        }

        .tab {
            padding: 8px 15px;
            background: #ddd;
            border-right: 1px solid #bbb;
            cursor: pointer;
            min-width: 80px;
            max-width: 120px;
            font-size: 0.9em;
            white-space: nowrap;
        }

        .tab.active {
            background: var(--window-bg);
            border-bottom: 2px solid white;
            margin-bottom: -1px;
        }

        #editor {
            width: 100%;
            height: 100%;
            border: none;
            resize: none;
            outline: none;
            padding: 10px;
            font-family: monospace;
            background: #fff;
        }

        .notepad-controls {
            display: flex;
            gap: 5px;
        }
    </style>
</head>
<body>

<div id="desktop">
    <!-- Files Window -->
    <div id="files-window" class="window" style="top: 100px; left: 100px;">
        <div class="title-bar">
            <span class="title">File Explorer</span>
            <button class="win-close">×</button>
        </div>
        <div class="window-content">
            <div id="files-path">/</div>
            <button id="files-up">.. (Up)</button>
            <hr style="margin: 15px 0;">
            <div id="files-list"></div>
        </div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window" style="top: 150px; left: 200px;">
        <div class="title-bar">
            <span class="title">Notepad</span>
            <div class="notepad-controls">
                <button id="new-tab" style="padding: 2px 8px; font-size: 10px;">+</button>
                <button class="win-close">×</button>
            </div>
        </div>
        <div id="tabs"></div>
        <div class="window-content" style="padding: 0;">
            <textarea id="editor"></textarea>
        </div>
    </div>

    <!-- Taskbar -->
    <div id="taskbar">
        <button id="open-files">Files</button>
        <button id="open-notepad">Notepad</button>
    </div>
</div>

<script>
    /** 
     * FILESYSTEM DATA & LOGIC
     */
    const fsData = {
        "/": ["bin", "etc", "home", "usr", "var"],
        "/home": ["user"],
        "/home/user": ["Documents", "Downloads", "Pictures", "secret.txt"],
        "/home/user/Documents": ["budget.xlsx", "resume.pdf"],
        "/home/user/Downloads": ["setup.exe", "image.png"],
        "/home/user/Pictures": ["vacation.jpg", "profile.png"]
    };

    let currentPath = "/";

    function renderFiles() {
        const listEl = document.getElementById('files-list');
        const pathEl = document.getElementById('files-path');
        listEl.innerHTML = "";
        pathEl.innerText = currentPath;

        const items = fsData[currentPath] || [];
        items.forEach(item => {
            const div = document.createElement('div');
            div.className = 'fs-item';
            // Check if it's a folder (if its path exists in our data)
            const fullPath = currentPath === "/" ? `/${item}` : `${currentPath}/${item}`;

            if (fsData[fullPath]) {
                div.classList.add('folder');
                div.onclick = () => {}; // Handled by dblclick
                div.ondblclick = () => {
                    currentPath = fullPath;
                    renderFiles();
                };
            } else {
                div.classList.add('file');
                div.ondblclick = () => alert("Cannot open file: " + item);
            }

            div.innerText = item;
            listEl.appendChild(div);
        });
    }

    document.getElementById('files-up').onclick = () => {
        if (currentPath === "/") return;
        const parts = currentPath.split('/').filter(p => p !== "");
        parts.pop();
        currentPath = "/" + parts.join("/");
        if (currentPath === "") currentPath = "/";
        renderFiles();
    };

    /** 
     * NOTEPAD LOGIC
     */
    let tabs = [];
    let activeTabId = null;

    function initNotepad() {
        const saved = localStorage.getItem('desktop_notepad_tabs');
        if (saved) {
            tabs = JSON.parse(saved);
            if (tabs.length > 0) activeTabId = tabs[0].id;
        } else {
            tabs = [{ id: Date.now(), title: "New Tab", content: "" }];
            activeTabId = tabs[0].id;
        }
        renderTabs();
    }

    function saveNotepad() {
        localStorage.setItem('desktop_notepad_tabs', JSON.stringify(tabs));
    }

    function renderTabs() {
        const container = document.getElementById('tabs');
        container.innerHTML = "";
        tabs.forEach(tab => {
            const tEl = document.createElement('div');
            tEl.className = `tab ${tab.id === activeTabId ? 'active' : ''}`;
            tEl.innerText = tab.title;
            tEl.onclick = () => {
                activeTabId = tab.id;
                renderTabs();
                updateEditorContent();
            };
            container.appendChild(tEl);
        });
    }

    function updateEditorContent() {
        const active = tabs.find(t => t.id === activeTabId);
        if (active) {
            document.getElementById('editor').value = active.content;
        }
    }

    document.getElementById('new-tab').onclick = () => {
        const newId = Date.now();
        tabs.push({ id: newId, title: `Tab ${tabs.length + 1}`, content: "" });
        activeTabId = newId;
        saveNotepad();
        renderTabs();
        updateEditorContent();
    };

    document.getElementById('editor').oninput = (e) => {
        const active = tabs.find(t => t.id === activeTabId);
        if (active) {
            active.content = e.target.value;
            saveNotepad();
        }
    };

    /** 
     * WINDOW MANAGEMENT & INTERACTION
     */
    function toggleWindow(id) {
        const win = document.getElementById(id);
        if (win.classList.contains('active')) {
            win.classList.remove('active');
        } else {
            // Ensure visibility and layout
            win.classList.add('active');
            if (id === 'notepad-window') initNotepad(); 
            if (id === 'files-window') renderFiles();
        }
    }

    document.getElementById('open-files').onclick = () => toggleWindow('files-window');
    document.getElementById('open-notepad').onclick = () => toggleWindow('notepad-window');

    document.querySelectorAll('.win-close').forEach(btn => {
        btn.onclick = (e) => {
            const win = e.target.closest('.window');
            win.classList.remove('active');
        };
    });

    // Draggable logic
    document.querySelectorAll('.title-bar').forEach(bar => {
        let isDragging = false;
        let offsetX, offsetY;

        bar.onmousedown = (e) => {
            const win = bar.closest('.window');
            isDragging = true;
            offsetX = e.clientX - win.offsetLeft;
            offsetY = e.clientY - win.offsetTop;
            win.style.zIndex = 1000; // Bring to front
        };

        document.onmousemove = (e) => {
            if (!isDragging) return;
            const win = bar.closest('.window');
            win.style.left = (e.clientX - offsetX) + 'px';
            win.style.top = (e.clientY - offsetY) + 'px';
        };

        document.onmouseup = () => {
            isDragging = false;
        };
    });

    // Initial State
    renderFiles();
    initNotepad();
</script>

</body>
</html>
